		expect(clippy?.args.slice(1)).toEqual(["cargo", "clippy", "--", "-W", "clippy::all"]);
		expect(clippy?.cwd).toBe(cwd);
		expect(plan.notes).toEqual([]);
	} finally {
		rmSync(root, { recursive: true, force: true });
	}

