		expect(run.stderr.toString()).toBe("");
		expect(run.exitCode).toBe(0);
		expect(JSON.parse(run.stdout.toString())).toEqual({ notes: [], results: [], diagnostics: "" });
	} finally {
		rmSync(cwd, { recursive: true, force: true });
	}
});

