	return /^\[package\]\s*$/m.test(toml);
}

/** Scaffold crates keep a `{{PLACEHOLDER}}` package name. They are not lint targets, and they fence off the crate around them. */
function isTemplateCargoManifest(toml: string): boolean {
	return hasPackageTable(toml) && /\bname\s*=\s*"\{\{/.test(toml);
}

export function findCargoPackageDir(
	filePath: string,
	exists: Exists = existsSync,
	readFile: ReadFile = readUtf8,
): string | undefined {
	for (let dir = dirname(filePath); ; dir = dirname(dir)) {
		const manifest = join(dir, "Cargo.toml");
